            [5776, 'وسایل نقلیه چپی واسقاطی', 9600000, null, '2024-11-03 10:52:45', '2024-11-03 10:52:45'],
            [5783, 'انواع حلال', 6620600, null, '2024-11-03 10:52:45', '2024-11-03 10:52:45'],
            [5784, 'سنگ ‌آهن دانه‌بندی‌شده', 3130100, null, '2024-11-03 10:52:45', '2024-11-03 10:52:45'],
            [5785, 'سنگ گچ دانه بندی شده', 3240110, null, null, null],
            [5787, 'بنتونيت فراوري شده', 3161310, null, null, null],
        ];

        $cargos = array_map(
            fn (array $cargo): array => [
                'id' => $cargo[0],
                'name' => $cargo[1],
                'code' => $cargo[2],
                'description' => $cargo[3],
                'created_at' => $cargo[4],
                'updated_at' => $cargo[5],
            ],
            $cargoRows,
        );

        Cargo::query()->upsert(
            $cargos,
            ['code'],
            ['name', 'description', 'created_at', 'updated_at'],
        );
    }
}
